// App.js — root component
// Handles auth gate and wraps everything in the shared PantryProvider context.
import { useState } from "react";
import { isSessionValid, destroySession } from "./utils/auth";
import { PantryProvider } from "./context/AppContext";
import { LockScreen } from "./components/LockScreen";
import { PantryShell } from "./features/PantryShell";

export default function App() {
  const [unlocked, setUnlocked] = useState(isSessionValid);

  if (!unlocked) {
    return <LockScreen onUnlock={() => setUnlocked(true)} />;
  }

  function handleLock() {
    destroySession();
    setUnlocked(false);
  }

  return (
    <PantryProvider onLock={handleLock}>
      <PantryShell />
    </PantryProvider>
  );
}
