// ─────────────────────────────────────────────────────────────────────────────
// components/HoldButton.js
// Fires once on pointer-down, then repeats while held. No double-fire on mobile.
// ─────────────────────────────────────────────────────────────────────────────
import { useRef } from "react";

export function HoldButton({ onPress, children, style, disabled }) {
  const timerRef    = useRef(null);
  const intervalRef = useRef(null);

  function start(e) {
    e.preventDefault();
    if (disabled) return;
    onPress();
    timerRef.current = setTimeout(() => {
      intervalRef.current = setInterval(() => onPress(), 80);
    }, 400);
  }

  function stop(e) {
    e.preventDefault();
    clearTimeout(timerRef.current);
    clearInterval(intervalRef.current);
  }

  return (
    <button
      onPointerDown={start}
      onPointerUp={stop}
      onPointerLeave={stop}
      onPointerCancel={stop}
      onClick={e => e.preventDefault()}
      disabled={disabled}
      style={{ ...style, userSelect:"none", WebkitUserSelect:"none", touchAction:"none" }}
    >
      {children}
    </button>
  );
}
