// features/scanner/ScanAddCard.js
import { useState } from "react";
import { Mo, SS } from "../../utils/theme";
import { HoldButton } from "../../components/HoldButton";
import { KITCHEN_ICON, STORAGE_ICON } from "../../constants";

// ─────────────────────────────────────────────────────────────────────────────
// Quick-add card — shown when barcode isn't recognised.
// Lets the user name + qty the item without leaving the scan context.
// ─────────────────────────────────────────────────────────────────────────────
function UnknownItemCard({
  barcode, pantryItems,
  onSave, onSaveAndMore, onEditFull, onSelectExisting, onCancel,
  ki = KITCHEN_ICON, si = STORAGE_ICON,
}) {
  const [name,   setName]   = useState("");
  const [brand,  setBrand]  = useState("");
  const [unit,   setUnit]   = useState("pcs");
  const [kitQty, setKitQty] = useState(1);
  const [stQty,  setStQty]  = useState(0);
  const [showLink, setShowLink] = useState(false);
  const [q,      setQ]      = useState("");

  const canSave = name.trim().length > 0;
  const filtered = (pantryItems || []).filter(i =>
    !q || i.name.toLowerCase().includes(q.toLowerCase()) ||
          (i.brand||"").toLowerCase().includes(q.toLowerCase()) ||
          (i.barcode||"").includes(q)
  );

  return (
    <div style={Mo.overlay}>
      <div style={{...Mo.modal, maxWidth:400, maxHeight:"90vh", display:"flex", flexDirection:"column"}}>
        {/* Header */}
        <div style={Mo.header}>
          <div>
            <span style={{fontFamily:"Fraunces,serif",fontSize:18,fontWeight:800}}>➕ New Item</span>
            <div style={{fontSize:11,color:"var(--text-dim)",marginTop:2,fontFamily:"DM Mono,monospace"}}>
              Barcode #{barcode} · not recognised
            </div>
          </div>
          <button onClick={onCancel} style={Mo.xBtn}>✕</button>
        </div>

        {/* Scrollable body */}
        <div style={{overflowY:"auto", flex:1, paddingBottom:4}}>

          {/* Name — auto-focused */}
          <div style={{marginBottom:10}}>
            <label style={SS.label}>
              Name <span style={{color:"var(--red)"}}>*</span>
            </label>
            <input
              autoFocus
              placeholder="e.g. Pasta, Olive Oil…"
              value={name}
              onChange={e => setName(e.target.value)}
              onKeyDown={e => e.key === "Enter" && canSave && onSave(name, brand, unit, kitQty, stQty)}
              style={{
                ...SS.input, marginTop:4, width:"100%", boxSizing:"border-box",
                fontSize:15, fontWeight:600,
              }}
            />
          </div>

          {/* Brand + Unit row */}
          <div style={{display:"flex", gap:8, marginBottom:14}}>
            <div style={{flex:2}}>
              <label style={SS.label}>Brand</label>
              <input
                placeholder="optional"
                value={brand}
                onChange={e => setBrand(e.target.value)}
                style={{...SS.input, marginTop:4, width:"100%", boxSizing:"border-box", fontSize:13}}
              />
            </div>
            <div style={{flex:1}}>
              <label style={SS.label}>Unit</label>
              <input
                value={unit}
                onChange={e => setUnit(e.target.value)}
                style={{...SS.input, marginTop:4, width:"100%", boxSizing:"border-box", fontSize:13}}
              />
            </div>
          </div>

          {/* Qty steppers */}
          <div style={{display:"flex", gap:10, marginBottom:14}}>
            <div style={{flex:1, background:"var(--accent-bg)", border:"1px solid var(--accent)", borderRadius:12, padding:"12px 10px"}}>
              <div style={{fontSize:12, color:"var(--accent)", fontWeight:600, marginBottom:10, textAlign:"center"}}>{ki} Kitchen</div>
              <div style={{display:"flex", gap:6, alignItems:"center", justifyContent:"center"}}>
                <HoldButton onPress={() => setKitQty(q => Math.max(0, q-1))} style={{...SS.qtyBtn, width:38, height:38, fontSize:20, flexShrink:0}}>−</HoldButton>
                <input style={{...SS.input, width:56, textAlign:"center", fontSize:20, fontWeight:800, padding:"7px 4px"}}
                  type="number" min={0} value={kitQty} onChange={e => setKitQty(Math.max(0, +e.target.value||0))}/>
                <HoldButton onPress={() => setKitQty(q => q+1)} style={{...SS.qtyBtn, width:38, height:38, fontSize:20, flexShrink:0}}>+</HoldButton>
              </div>
            </div>
            <div style={{flex:1, background:"var(--blue-bg)", border:"1px solid var(--blue)", borderRadius:12, padding:"12px 10px"}}>
              <div style={{fontSize:12, color:"var(--blue)", fontWeight:600, marginBottom:10, textAlign:"center"}}>{si} Storage</div>
              <div style={{display:"flex", gap:6, alignItems:"center", justifyContent:"center"}}>
                <HoldButton onPress={() => setStQty(q => Math.max(0, q-1))} style={{...SS.qtyBtn, width:38, height:38, fontSize:20, flexShrink:0}}>−</HoldButton>
                <input style={{...SS.input, width:56, textAlign:"center", fontSize:20, fontWeight:800, padding:"7px 4px"}}
                  type="number" min={0} value={stQty} onChange={e => setStQty(Math.max(0, +e.target.value||0))}/>
                <HoldButton onPress={() => setStQty(q => q+1)} style={{...SS.qtyBtn, width:38, height:38, fontSize:20, flexShrink:0}}>+</HoldButton>
              </div>
            </div>
          </div>

          {/* Actions */}
          <div style={{display:"flex", flexDirection:"column", gap:8}}>
            <button
              onClick={() => canSave && onSave(name, brand, unit, kitQty, stQty)}
              disabled={!canSave}
              style={{...SS.primaryBtn, opacity:canSave?1:0.4}}
            >
              ✓ Save
            </button>
            <button
              onClick={() => canSave && onSaveAndMore(name, brand, unit, kitQty, stQty)}
              disabled={!canSave}
              style={{...SS.secondaryBtn, textAlign:"center", opacity:canSave?1:0.4}}
            >
              ✓ Save + Scan more
            </button>
            <button
              onClick={() => onEditFull(name, brand, unit, kitQty, stQty)}
              style={{...SS.secondaryBtn, textAlign:"center", fontSize:12}}
            >
              ✏️ Edit full details first
            </button>
          </div>

          {/* Link to existing — collapsible */}
          <div style={{marginTop:14, borderTop:"1px solid var(--border)", paddingTop:10}}>
            <button
              onClick={() => setShowLink(l => !l)}
              style={{
                background:"none", border:"none", cursor:"pointer",
                fontSize:12, color:"var(--text-dim)", padding:0,
                width:"100%", textAlign:"left",
                display:"flex", alignItems:"center", gap:4,
              }}
            >
              <span>{showLink ? "▾" : "▸"}</span>
              <span>It's actually an existing item in my pantry…</span>
            </button>

            {showLink && (
              <div style={{marginTop:8}}>
                <input
                  autoFocus
                  placeholder="Search your pantry…"
                  value={q}
                  onChange={e => setQ(e.target.value)}
                  style={{...SS.input, width:"100%", boxSizing:"border-box", padding:"8px 12px", fontSize:13}}
                />
                <div style={{maxHeight:200, overflowY:"auto", marginTop:4}}>
                  {filtered.length === 0 && (
                    <div style={{textAlign:"center", color:"var(--text-dim)", fontSize:13, padding:"12px 0"}}>No items match</div>
                  )}
                  {filtered.map(item => (
                    <button key={item.id} onClick={() => onSelectExisting(item)}
                      style={{
                        width:"100%", display:"flex", alignItems:"center", gap:10,
                        padding:"8px 12px", background:"none", border:"none",
                        borderBottom:"1px solid var(--border)", cursor:"pointer", textAlign:"left",
                      }}
                    >
                      {item.image
                        ? <img src={item.image} alt="" style={{width:36,height:36,objectFit:"contain",borderRadius:6,background:"#fff",flexShrink:0}} onError={e=>e.target.style.display="none"}/>
                        : <div style={{width:36,height:36,background:"var(--surface2)",borderRadius:6,display:"flex",alignItems:"center",justifyContent:"center",fontSize:16,flexShrink:0}}>🥫</div>
                      }
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{fontFamily:"Fraunces,serif",fontSize:13,fontWeight:600,color:"var(--text)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{item.name||"Unnamed"}</div>
                        {item.brand && <div style={{fontSize:11,color:"var(--text-mid)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{item.brand}</div>}
                      </div>
                      <div style={{display:"flex",gap:6,flexShrink:0}}>
                        <div style={{textAlign:"center"}}>
                          <div style={{fontSize:10,color:"var(--accent)",fontWeight:600}}>{ki}</div>
                          <div style={{fontSize:12,fontWeight:700,color:"var(--text)"}}>{item.kitchenQty}</div>
                        </div>
                        <div style={{textAlign:"center"}}>
                          <div style={{fontSize:10,color:"var(--blue)",fontWeight:600}}>{si}</div>
                          <div style={{fontSize:12,fontWeight:700,color:"var(--text)"}}>{item.storageQty}</div>
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

        </div>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Main scan add card — handles both new and existing item flows
// ─────────────────────────────────────────────────────────────────────────────
export function ScanAddCard({
  scannedItem, existing, fallback, pantryItems, barcode: rawBarcode,
  scanLocation, onSelectExisting,
  onSave, onSaveAndMore, onEditFull, onCancel,
  onSaveNew, onSaveAndMoreNew, onEditFullNew,
  ki = KITCHEN_ICON, si = STORAGE_ICON,
}) {
  const [kitQty, setKitQty] = useState(1);
  const [stQty,  setStQty]  = useState(0);
  const [addQty, setAddQty] = useState(1);
  const [loc,    setLoc]    = useState(scanLocation || "kitchen");
  const isExist = !!existing;
  const curQty = isExist ? (loc === "kitchen" ? existing.kitchenQty : existing.storageQty) : 0;

  if (fallback) {
    return (
      <UnknownItemCard
        barcode={rawBarcode || ""}
        pantryItems={pantryItems}
        onSave={onSaveNew}
        onSaveAndMore={onSaveAndMoreNew}
        onEditFull={onEditFullNew}
        onSelectExisting={onSelectExisting}
        onCancel={onCancel}
        ki={ki} si={si}
      />
    );
  }

  return (
    <div style={Mo.overlay}><div style={{...Mo.modal,maxWidth:390}}>
      <div style={Mo.header}>
        <span style={{fontFamily:"Fraunces,serif",fontSize:18,fontWeight:800}}>
          {isExist ? "📦 Restock" : "➕ New Item"}
        </span>
        <button onClick={onCancel} style={Mo.xBtn}>✕</button>
      </div>

      {/* Product info */}
      <div style={{display:"flex",gap:12,alignItems:"center",marginBottom:14,padding:12,
        background:"var(--surface2)",borderRadius:10}}>
        {(scannedItem.image||existing?.image) && (
          <img src={scannedItem.image||existing?.image} alt=""
            style={{width:50,height:50,objectFit:"contain",borderRadius:8,
              background:"#fff",flexShrink:0}}
            onError={e=>e.target.style.display="none"}/>
        )}
        <div style={{flex:1}}>
          <div style={{fontFamily:"Fraunces,serif",fontSize:15,fontWeight:700}}>
            {scannedItem.name||existing?.name||"Unknown product"}
          </div>
          {(scannedItem.brand||existing?.brand) && (
            <div style={{fontSize:12,color:"var(--text-mid)",marginTop:2}}>
              {scannedItem.brand||existing?.brand}
            </div>
          )}
        </div>
      </div>

      {isExist ? (
        <>
          {/* Current stock */}
          <div style={{display:"flex",gap:8,marginBottom:14}}>
            <div style={{flex:1,padding:"10px 12px",background:"var(--surface2)",
              borderRadius:8,textAlign:"center"}}>
              <div style={{fontSize:10,color:"var(--accent)",fontWeight:600,marginBottom:3}}>{ki} KITCHEN</div>
              <div style={{fontSize:16,fontWeight:700,color:"var(--text)"}}>
                {existing.kitchenQty} <span style={{fontSize:11,color:"var(--text-mid)"}}>{existing.unit}</span>
              </div>
            </div>
            <div style={{flex:1,padding:"10px 12px",background:"var(--blue-bg)",
              borderRadius:8,textAlign:"center"}}>
              <div style={{fontSize:10,color:"var(--blue)",fontWeight:600,marginBottom:3}}>{si} STORAGE</div>
              <div style={{fontSize:16,fontWeight:700,color:"var(--text)"}}>
                {existing.storageQty} <span style={{fontSize:11,color:"var(--text-mid)"}}>{existing.unit}</span>
              </div>
            </div>
          </div>
          {/* Location selector */}
          <div style={{display:"flex",gap:8,marginBottom:14}}>
            {["kitchen","storage"].map(l=>(
              <button key={l} onClick={()=>setLoc(l)}
                style={{flex:1,padding:"8px",borderRadius:8,cursor:"pointer",
                  border:`1px solid ${loc===l?(l==="kitchen"?"var(--accent)":"var(--blue)"):"var(--border)"}`,
                  background:loc===l?(l==="kitchen"?"var(--accent-bg)":"var(--blue-bg)"):"transparent",
                  color:loc===l?(l==="kitchen"?"var(--accent)":"var(--blue)"):"var(--text-mid)",
                  fontFamily:"DM Mono,monospace",fontSize:12}}>
                {l==="kitchen"?`${ki} Kitchen`:`${si} Storage`}
              </button>
            ))}
          </div>
          {/* Add qty */}
          <div style={{marginBottom:18}}>
            <label style={SS.label}>Add to {loc}:</label>
            <div style={{display:"flex",gap:10,alignItems:"center",marginTop:6}}>
              <HoldButton onPress={()=>setAddQty(q=>Math.max(1,q-1))}
                style={{...SS.qtyBtn,width:44,height:44,fontSize:20}}>−</HoldButton>
              <input style={{...SS.input,flex:1,textAlign:"center",fontSize:20,fontWeight:700}}
                type="number" min={1} value={addQty}
                onChange={e=>setAddQty(Math.max(1,+e.target.value))}/>
              <HoldButton onPress={()=>setAddQty(q=>q+1)}
                style={{...SS.qtyBtn,width:44,height:44,fontSize:20}}>+</HoldButton>
            </div>
            <div style={{fontSize:12,color:"var(--green)",marginTop:8,textAlign:"center"}}>
              {loc} total: <b>{curQty+addQty} {existing.unit}</b>
            </div>
          </div>
          <div style={{display:"flex",flexDirection:"column",gap:8}}>
            <button onClick={()=>onSave(addQty,loc)} style={SS.primaryBtn}>✓ Save (+{addQty})</button>
            <button onClick={()=>onSaveAndMore(addQty,loc)}
              style={{...SS.secondaryBtn,textAlign:"center"}}>✓ Save + Scan more</button>
            <button onClick={onCancel}
              style={{...SS.secondaryBtn,textAlign:"center",fontSize:12}}>Cancel</button>
          </div>
        </>
      ) : (
        <>
          {/* New item: independent kitchen + storage qty */}
          <div style={{marginBottom:6}}>
            <div style={{fontSize:11,color:"var(--text-mid)",marginBottom:10,textAlign:"center"}}>
              Set how many go to each location:
            </div>
            <div style={{display:"flex",gap:10,marginBottom:10}}>
              <div style={{flex:1,background:"var(--accent-bg)",border:"1px solid var(--accent)",
                borderRadius:12,padding:"12px 10px"}}>
                <div style={{fontSize:12,color:"var(--accent)",fontWeight:600,marginBottom:10,textAlign:"center"}}>
                  {ki} Kitchen
                </div>
                <div style={{display:"flex",gap:6,alignItems:"center",justifyContent:"center"}}>
                  <HoldButton onPress={()=>setKitQty(q=>Math.max(0,q-1))}
                    style={{...SS.qtyBtn,width:38,height:38,fontSize:20,flexShrink:0}}>−</HoldButton>
                  <input style={{...SS.input,width:56,textAlign:"center",fontSize:20,fontWeight:800,padding:"7px 4px"}}
                    type="number" min={0} value={kitQty}
                    onChange={e=>setKitQty(Math.max(0,+e.target.value||0))}/>
                  <HoldButton onPress={()=>setKitQty(q=>q+1)}
                    style={{...SS.qtyBtn,width:38,height:38,fontSize:20,flexShrink:0}}>+</HoldButton>
                </div>
              </div>
              <div style={{flex:1,background:"var(--blue-bg)",border:"1px solid var(--blue)",
                borderRadius:12,padding:"12px 10px"}}>
                <div style={{fontSize:12,color:"var(--blue)",fontWeight:600,marginBottom:10,textAlign:"center"}}>
                  {si} Storage
                </div>
                <div style={{display:"flex",gap:6,alignItems:"center",justifyContent:"center"}}>
                  <HoldButton onPress={()=>setStQty(q=>Math.max(0,q-1))}
                    style={{...SS.qtyBtn,width:38,height:38,fontSize:20,flexShrink:0}}>−</HoldButton>
                  <input style={{...SS.input,width:56,textAlign:"center",fontSize:20,fontWeight:800,padding:"7px 4px"}}
                    type="number" min={0} value={stQty}
                    onChange={e=>setStQty(Math.max(0,+e.target.value||0))}/>
                  <HoldButton onPress={()=>setStQty(q=>q+1)}
                    style={{...SS.qtyBtn,width:38,height:38,fontSize:20,flexShrink:0}}>+</HoldButton>
                </div>
              </div>
            </div>
            <div style={{padding:"10px 14px",background:"var(--surface2)",
              border:"1px solid var(--border)",borderRadius:10,textAlign:"center"}}>
              <span style={{fontSize:12,color:"var(--text-mid)"}}>Total: </span>
              <span style={{fontSize:16,fontWeight:800,
                color:kitQty+stQty>0?"var(--green)":"var(--text-dim)"}}>{kitQty+stQty}</span>
              <span style={{fontSize:11,color:"var(--text-dim)",marginLeft:6}}>
                ({kitQty} kitchen + {stQty} storage)
              </span>
            </div>
          </div>
          <div style={{display:"flex",flexDirection:"column",gap:8,marginTop:14}}>
            <button onClick={()=>onSave(kitQty,stQty)} disabled={kitQty+stQty===0}
              style={{...SS.primaryBtn,opacity:kitQty+stQty>0?1:0.4}}>✓ Save</button>
            <button onClick={()=>onSaveAndMore(kitQty,stQty)} disabled={kitQty+stQty===0}
              style={{...SS.secondaryBtn,textAlign:"center",opacity:kitQty+stQty>0?1:0.4}}>
              ✓ Save + Scan more
            </button>
            <button onClick={()=>onEditFull(kitQty,stQty)}
              style={{...SS.secondaryBtn,textAlign:"center",fontSize:12}}>✏️ Edit details first</button>
            <button onClick={onCancel}
              style={{...SS.secondaryBtn,textAlign:"center",fontSize:12}}>Cancel</button>
          </div>
        </>
      )}
    </div></div>
  );
}
