// features/scanner/ScanModals.js — review/history modals used with scanning
import { Mo } from "../../utils/theme";
import { fmtDate } from "../../utils/expiry";
import { HoldButton } from "../../components/HoldButton";

export function RemoveReviewModal({ removals, onConfirm, onCancel, onAdjust }) {
  return (
    <div style={Mo.overlay}><div style={Mo.modal}>
      <div style={Mo.header}>
        <span style={{fontFamily:"Fraunces,serif",fontSize:19,fontWeight:800}}>📤 Review Removals</span>
        <button onClick={onCancel} style={Mo.xBtn}>✕</button>
      </div>
      <div style={{display:"flex",flexDirection:"column",gap:8,maxHeight:340,overflowY:"auto"}}>
        {removals.map((r,i) => (
          <div key={r.item.id} style={Mo.row}>
            <div style={{flex:1}}>
              <div style={{fontFamily:"Fraunces,serif",fontSize:13,fontWeight:600}}>{r.item.name}</div>
              <div style={{fontSize:11,color:"var(--text-mid)",marginTop:2}}>
                Removing from:{" "}
                <b style={{color:r.location==="kitchen"?"var(--accent)":"var(--blue)"}}>
                  {r.location==="kitchen"?"Kitchen":"Storage"}
                </b>{" "}
                · In stock: <b style={{color:"var(--text)"}}>
                  {r.location==="kitchen"?r.item.kitchenQty:r.item.storageQty} {r.item.unit}
                </b>
              </div>
            </div>
            <div style={{display:"flex",alignItems:"center",gap:6}}>
              <HoldButton onPress={()=>onAdjust(i,-1)} style={Mo.qBtn} disabled={r.removeQty<=1}>−</HoldButton>
              <span style={{fontSize:14,fontWeight:700,minWidth:22,textAlign:"center",color:"var(--red)"}}>{r.removeQty}</span>
              <HoldButton onPress={()=>onAdjust(i,1)} style={Mo.qBtn}
                disabled={r.removeQty>=(r.location==="kitchen"?r.item.kitchenQty:r.item.storageQty)}>+</HoldButton>
              <button onClick={()=>onAdjust(i,0)}
                style={{...Mo.qBtn,color:"var(--red)",borderColor:"var(--red-bg)",marginLeft:4}}>✕</button>
            </div>
          </div>
        ))}
      </div>
      <div style={{display:"flex",gap:8,marginTop:18,justifyContent:"flex-end"}}>
        <button onClick={onCancel} style={Mo.cancelBtn}>Cancel</button>
        <button onClick={onConfirm} style={Mo.confirmBtn}>Confirm</button>
      </div>
    </div></div>
  );
}

export function HistoryModal({ item, onClose }) {
  const h  = [...(item.history || [])].reverse();
  const tL = { add:"Added", remove:"Removed", move:"Moved", create:"Created", set:"Set" };
  const tC = { add:"var(--green)", remove:"var(--red)", move:"var(--blue)", create:"var(--text-dim)", set:"var(--accent)" };
  const qSign = { add:"+", remove:"−", create:"", move:"→", set:"=" };
  return (
    <div style={Mo.overlay}><div style={{...Mo.modal,maxWidth:440}}>
      <div style={Mo.header}>
        <div>
          <span style={{fontFamily:"Fraunces,serif",fontSize:18,fontWeight:800}}>📋 {item.name}</span>
          <div style={{fontSize:11,color:"var(--text-dim)",marginTop:2}}>{h.length} change{h.length!==1?"s":""} · {item.unit}</div>
        </div>
        <button onClick={onClose} style={Mo.xBtn}>✕</button>
      </div>
      {h.length === 0
        ? <div style={{color:"var(--text-dim)",fontSize:13,textAlign:"center",padding:"20px 0"}}>No history yet.</div>
        : <div style={{display:"flex",flexDirection:"column",gap:4,maxHeight:440,overflowY:"auto"}}>
            {h.map(e => (
              <div key={e.id} style={{
                display:"grid", gridTemplateColumns:"3px 1fr auto",
                gap:0, borderRadius:8, overflow:"hidden",
                background:"var(--surface2)",
              }}>
                {/* Colour bar */}
                <div style={{background:tC[e.type]||"var(--border)"}}/>
                {/* Content */}
                <div style={{padding:"9px 12px"}}>
                  <div style={{display:"flex",alignItems:"baseline",gap:8,flexWrap:"wrap"}}>
                    <span style={{color:tC[e.type],fontSize:13,fontWeight:700}}>
                      {tL[e.type]||e.type}
                    </span>
                    {e.qty!=null&&e.qty!==0&&(
                      <span style={{fontSize:15,fontWeight:800,color:"var(--text)"}}>
                        {qSign[e.type]||""}{e.qty} {item.unit}
                      </span>
                    )}
                    {e.note&&(
                      <span style={{fontSize:11,color:"var(--text-mid)",fontStyle:"italic"}}>
                        {e.note}
                      </span>
                    )}
                  </div>
                  {e.by&&(
                    <div style={{fontSize:11,color:"var(--blue)",marginTop:3,display:"flex",alignItems:"center",gap:4}}>
                      <span style={{opacity:0.6}}>by</span>
                      <span style={{fontWeight:600}}>{e.by}</span>
                    </div>
                  )}
                </div>
                {/* Timestamp */}
                <div style={{padding:"9px 12px",display:"flex",flexDirection:"column",alignItems:"flex-end",justifyContent:"center",gap:2,flexShrink:0}}>
                  <span style={{fontSize:11,color:"var(--text-dim)",whiteSpace:"nowrap"}}>{fmtDate(e.at)}</span>
                </div>
              </div>
            ))}
          </div>}
      <div style={{display:"flex",justifyContent:"flex-end",marginTop:16}}>
        <button onClick={onClose} style={Mo.cancelBtn}>Close</button>
      </div>
    </div></div>
  );
}
