/** Inject CSS custom properties for the chosen theme into a <style> tag. */
export function buildThemeCSS(tm) {
  return `:root{
    --bg:${tm.bg}; --surface:${tm.surface}; --surface2:${tm.surface2}; --surface3:${tm.surface3};
    --border:${tm.border}; --border2:${tm.border2};
    --text:${tm.text}; --text-mid:${tm.textMid}; --text-dim:${tm.textDim};
    --accent:${tm.accent}; --accent-bg:${tm.accentBg};
    --green:${tm.green}; --green-bg:${tm.greenBg};
    --blue:${tm.blue}; --blue-bg:${tm.blueBg};
    --red:${tm.red}; --red-bg:${tm.redBg};
    --orange:${tm.orange}; --shadow:${tm.shadow};
  }
  body{background:var(--bg);color:var(--text);}
  input,select,textarea,option{background:var(--surface2)!important;color:var(--text)!important;}
  ::-webkit-scrollbar-track{background:var(--surface);}
  ::-webkit-scrollbar-thumb{background:var(--border2);border-radius:3px;}`;
}

