export const globalCSS = `
  @import url('https://fonts.googleapis.com/css2?family=Fraunces:wght@300;600;800&family=DM+Mono:wght@400;500&display=swap');
  *,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}
  body{font-family:'DM Mono',monospace;}
  ::-webkit-scrollbar{width:5px;}
  input,select,textarea{font-family:'DM Mono',monospace;}
  details>summary{list-style:none;}details>summary::-webkit-details-marker{display:none;}
  details[open]>summary span:first-child{transform:rotate(90deg);display:inline-block;}
  @keyframes fadeIn{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:translateY(0);}}
  @keyframes pulse{0%,100%{opacity:1;}50%{opacity:0.4;}}
  @keyframes scanLine{0%{top:5%;}100%{top:90%;}}
  @keyframes toastIn{from{opacity:0;transform:translateX(40px);}to{opacity:1;transform:translateX(0);}}
  @keyframes spin{from{transform:rotate(0deg);}to{transform:rotate(360deg);}}
  .item-card{transition:transform 0.18s ease,box-shadow 0.18s ease;animation:fadeIn 0.3s ease both;}
  .item-card:hover{transform:translateY(-2px);box-shadow:0 6px 24px var(--shadow)!important;}
  .fab-btn{transition:transform 0.15s ease,filter 0.15s ease;cursor:pointer;}
  .fab-btn:hover{transform:translateY(-3px);filter:brightness(1.1);}
  .nav-btn:hover{color:var(--accent)!important;}
`;

