// ─────────────────────────────────────────────────────────────────────────────
// utils/crypto.js  — AES-256-GCM encrypt / decrypt for shared pantry data
// ─────────────────────────────────────────────────────────────────────────────

async function deriveKey(password, salt) {
  const enc  = new TextEncoder();
  const base = await crypto.subtle.importKey(
    "raw", enc.encode(password), "PBKDF2", false, ["deriveKey"]
  );
  return crypto.subtle.deriveKey(
    { name:"PBKDF2", salt:enc.encode(salt), iterations:200000, hash:"SHA-256" },
    base, { name:"AES-GCM", length:256 }, false, ["encrypt","decrypt"]
  );
}

export async function encryptData(data, password) {
  const salt    = crypto.getRandomValues(new Uint8Array(16));
  const iv      = crypto.getRandomValues(new Uint8Array(12));
  const key     = await deriveKey(password, Array.from(salt).join(","));
  const ct      = await crypto.subtle.encrypt(
    { name:"AES-GCM", iv }, key,
    new TextEncoder().encode(JSON.stringify(data))
  );
  const combined = new Uint8Array(28 + ct.byteLength);
  combined.set(salt, 0); combined.set(iv, 16); combined.set(new Uint8Array(ct), 28);
  return btoa(String.fromCharCode(...combined));
}

export async function decryptData(b64, password) {
  const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
  const key   = await deriveKey(password, Array.from(bytes.slice(0,16)).join(","));
  const plain = await crypto.subtle.decrypt(
    { name:"AES-GCM", iv:bytes.slice(16,28) }, key, bytes.slice(28)
  );
  return JSON.parse(new TextDecoder().decode(plain));
}
