// ─────────────────────────────────────────────────────────────────────────────
// utils/expiry.js  — date maths and expiry colour/label helpers
// ─────────────────────────────────────────────────────────────────────────────

export function daysUntil(d) {
  if (!d) return null;
  return Math.ceil((new Date(d) - new Date()) / 86400000);
}

/** Returns a CSS colour string based on days remaining + warning threshold. */
export function expColor(days, threshold = 30) {
  if (days === null)       return "#555";
  if (days < 0)            return "#e63312";   // expired
  if (days <= 3)           return "#e63312";   // 0-3 d — red
  if (days <= 7)           return "#e77d00";   // 4-7 d — orange
  if (days <= 14)          return "#f7c800";   // 8-14 d — yellow
  if (days <= threshold)   return "#f7c800";   // within warn window
  return "#4caf7d";                            // safe — green
}

/** Returns a short human-readable label, or null when expiry is far away. */
export function expLabel(days, threshold = 30) {
  if (days === null)      return null;
  if (days < 0)           return `⚠ Expired ${Math.abs(days)}d ago`;
  if (days === 0)         return "⚠ Expires today!";
  if (days === 1)         return "⚠ Tomorrow!";
  if (days <= 7)          return `⚠ ${days}d left`;
  if (days <= threshold)  return `📅 ${days}d left`;
  return null;
}

export function fmtDate(iso) {
  if (!iso) return "";
  return new Date(iso).toLocaleDateString(undefined, {
    day:"2-digit", month:"short", hour:"2-digit", minute:"2-digit",
  });
}
