// features/settings/SettingsComponents.js
import { useState } from "react";

export function SettingsRow({ label, hint, children }) {
  return (
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",
      gap:12,padding:"10px 0",borderBottom:"1px solid var(--border)"}}>
      <div style={{flex:1,minWidth:0}}>
        <div style={{fontSize:13,color:"var(--text)"}}>{label}</div>
        {hint&&<div style={{fontSize:10,color:"var(--text-dim)",marginTop:2}}>{hint}</div>}
      </div>
      <div style={{flexShrink:0}}>{children}</div>
    </div>
  );
}

export function SettingsSection({ icon, title, children, defaultOpen = false }) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div style={{marginBottom:10,background:"var(--surface)",border:"1px solid var(--border)",
      borderRadius:12,overflow:"hidden"}}>
      <button onClick={()=>setOpen(o=>!o)}
        style={{width:"100%",display:"flex",alignItems:"center",justifyContent:"space-between",
          padding:"13px 16px",background:"transparent",border:"none",cursor:"pointer",
          color:"var(--text)",textAlign:"left"}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:18}}>{icon}</span>
          <span style={{fontFamily:"Fraunces,serif",fontSize:15,fontWeight:700}}>{title}</span>
        </div>
        <span style={{fontSize:12,color:"var(--text-dim)",transition:"transform 0.2s",
          transform:open?"rotate(180deg)":"none"}}>▼</span>
      </button>
      {open&&<div style={{padding:"4px 16px 16px"}}>{children}</div>}
    </div>
  );
}
